1083:     const shadowAware = lower.includes('shadow') || lower.includes('pattern') || lower.includes('growth') || lower.includes('heal');
1084:     const awarenessBonus = shadowAware ? 0.1 : 0;
1085:     const semanticBonus = lengthBonus + densityBonus + awarenessBonus;
1086: 
1087:     // Apply semantic bonus to all scores (caps at 1.0)
1088:     const adjustedAgencyScore = Math.min(1.0, agencyScore + (selectedDrive === 'agency' ? semanticBonus : 0));
1089:     const adjustedCommunionScore = Math.min(1.0, communionScore + (selectedDrive === 'communion' ? semanticBonus : 0));
1090:     const adjustedErosScore = Math.min(1.0, erosScore + (selectedDrive === 'eros' ? semanticBonus : 0));
1091:     const adjustedAgapeScore = Math.min(1.0, agapeScore + (selectedDrive === 'agape' ? semanticBonus : 0));
1092: 
1093:     const avgScore = (adjustedAgencyScore + adjustedCommunionScore + adjustedErosScore + adjustedAgapeScore) / 4;
1094:     const passThreshold = module.scoringRubric.passThreshold ?? 0.5;
1095:     const passed = avgScore >= passThreshold;
1096: 
1097:     // Build feedback with depth-adjusted scores
1098:     const depthNote = semanticBonus > 0
1099:       ? ` (${wordCount} words, ${(conceptDensity * 100).toFixed(0)}% unique, +${(semanticBonus * 100).toFixed(0)}% depth)`
1100:       : '';
1101:     const feedback = passed
1102:       ? `Your response demonstrated balanced engagement with the ${module.line} ${module.stage} challenge. Agency: ${(adjustedAgencyScore * 100).toFixed(0)}%, Communion: ${(adjustedCommunionScore * 100).toFixed(0)}%, Eros: ${(adjustedErosScore * 100).toFixed(0)}%, Agape: ${(adjustedAgapeScore * 100).toFixed(0)}%.${depthNote}`
1103:       : `The challenge revealed areas for growth. Your ${module.line} ${module.stage} response showed room for deeper integration.`;
1104: 
1105:     return {
1106:       passed,
1107:       polarityDirection,
1108:       driveScores: { agency: adjustedAgencyScore, communion: adjustedCommunionScore, eros: adjustedErosScore, agape: adjustedAgapeScore },
1109:       driveSignals: {
1110:         agency: agencyResult.signal,
1111:         communion: communionResult.signal,
1112:         eros: erosResult.signal,
