1138:   /**
1139:    * Compute an altitude shift signal when the player demonstrates consistent
1140:    * HealthyBalanced drive patterns across ALL 4 drives (selected drive must score
1141:    * healthy, not shadow).
1142:    * Returns a ConsequenceRecord-compatible object or null if no shift is warranted.
1143:    */
1144:   private computeAltitudeShift(
1145:     _driveSignals: { agency: string; communion: string; eros: string; agape: string },
1146:     module: StageAssessment,
1147:     currentEncounterStage: Stage,
1148:     passed: boolean,
1149:   ): { line: Line; from: Stage; to: Stage } | null {
1150:     const key = module.line;
1151: 
1152:     if (!passed) {
1153:       return null; // Failures don't count but don't reset total count either
1154:     }
1155: 
1156:     // Use TOTAL passes per line (not consecutive) — the scheduler alternates lines
1157:     // so consecutive passes are mathematically impossible with 8+ lines.
1158:     // Threshold of 2 passes: demonstrates sustained capacity on the same line.
1159:     const totalPasses = (this._consecutivePasses.get(key) ?? 0) + 1;
1160:     this._consecutivePasses.set(key, totalPasses);
1161: 
1162:     if (totalPasses < 2) {
1163:       return null; // Need at least 2 passes on this line
1164:     }
1165: 
1166:     // Shift achieved — reset counter so future passes require 2 fresh wins
1167:     this._consecutivePasses.set(key, 0);
1168:     return { line: module.line, from: currentEncounterStage, to: currentEncounterStage };
