143:     codexEntries: newCodexEntries,
144:     totalEncounters: sig.totalEncounters + 1,
145:   };
146: 
147:   // 6. Update NPC Relationships and recentEncounterIds
148:   const npcRelationships = [...world.npcRelationships];
149: 
150:   // Update or initialize relationship for the primary holonSource if present
151:   if (encounter.holonSource) {
152:     const holonId = encounter.holonSource;
153:     const existingIdx = npcRelationships.findIndex(r => r.holonId === holonId);
154:     if (existingIdx !== -1) {
155:       const existing = npcRelationships[existingIdx];
156:       npcRelationships[existingIdx] = {
