243:   const newFixation = { ...current.fixationRisk };
244: 
245:   for (const drive of drives) {
246:     const signal = directionality[drive];
247:     switch (signal) {
248:       case 'DarkAddicted':
249:       case 'GoldenAddicted':
250:         newWeights[drive] = (newWeights[drive] ?? 0) + 0.03;
251:         newFixation[drive] = Math.min(1, (newFixation[drive] ?? 0) + 0.05);
