253:       case 'DarkAverted':
254:       case 'GoldenAverted':
255:         newWeights[drive] = (newWeights[drive] ?? 0) - 0.02;
256:         newFixation[drive] = Math.min(1, (newFixation[drive] ?? 0) + 0.03);
257:         break;
258:       case 'HealthyBalanced':
259:         newWeights[drive] = (newWeights[drive] ?? 0) + 0.01;
260:         newFixation[drive] = Math.max(0, (newFixation[drive] ?? 0) - 0.02);
261:         break;
262:     }
263:   }
